export const workingConditionQuery = `
  query WorkingConditionForecast($yearStart: timestamp!, $yearEnd: timestamp!) {
    EmployeeWorkingCondition(
      where: {
        _and: [
          { hireDate: { _lte: $yearEnd } },
          { _or: [
              { exitDate: { _isNull: true } },
              { exitDate: { _gte: $yearStart } }
          ]}
        ]
      }
    ) {
      id
      employeeId
      hireDate
      exitDate
      monthlyGrossSalary
      annualGrossSalary
      hourlyGrossSalary
      employmentType { value }
      contractType { value }
      region { value }
      remote { value }
      probationEnd
      currency { code }
    }
    EmployeeWorkingConditionAggregate {
      aggregate {
        count
      }
    }
  }
`","numLines":35,"startLine":2,"totalLines":36}}

{"type":"text","file":{"filePath":"/tmp/every-agent-VYayg8/repo/src/business-apps/hr/core/apps/human-resources/components/views/analytics-view/hooks/useWorkingConditionForecast.ts","content":"import { useGraphqlClient } from '@/common/network/graphql/useGraphQLClient'
import { workingConditionQuery } from '../queries/workingCondition'
import { BusinessAppContextProps } from '../../../../../../common/BusinessAppContext'

export interface WorkingConditionKpi {
  id: string
  employeeId: string
  hireDate: string | null
  exitDate: string | null
  monthlyGrossSalary: number | null
  annualGrossSalary: number | null
  hourlyGrossSalary: number | null
  employmentType?: { value: string } | null
  contractType?: { value: string } | null
  region?: { value: string } | null
  remote?: any
  probationEnd?: string | null
  currency?: { value: string } | null
}

export interface WorkingConditionKpiResult {
  data: WorkingConditionKpi[]
  count: number
  loading: boolean
  error: any
}

export const useWorkingConditionForecast = (props: BusinessAppContextProps): WorkingConditionKpiResult => {
  const [data, setData] = useState<WorkingConditionKpi[]>([])
  const [count, setCount] = useState<number>(0)
  const [loading, setLoading] = useState<boolean>(false)
  const [error, setError] = useState<any>(null)

  const client = useGraphqlClient(props.accessToken)

  useEffect(() => {
    setLoading(true)
    // Calculate current year range
    const now = new Date()
    const year = now.getFullYear()
    const yearStart = `${year}-01-01`
    const yearEnd = `${year}-12-31`
    client
      .request(workingConditionQuery, {
        yearStart,
        yearEnd
      })
      .then((res: any) => {
        setData(res.EmployeeWorkingCondition || [])
        setCount(res.EmployeeWorkingConditionAggregate?.aggregate?.count || 0)
        setError(null)
      })
      .catch(setError)
      .finally(() => setLoading(false))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [props.accessToken])

  return { data, count, loading, error }
}","numLines":59,"startLine":2,"totalLines":60}}

